import {base,recipes,key,validateResult} from './recipes.js';
import {extractions} from './extractions.js';
const $=s=>document.querySelector(s),storageKey='element-lab-share-v1';
let elements=[...base],history=[],cache={},settings={mode:'classic',endpoint:''},slots=[null,null],busy=false,ready=false,filter='all',favoritesOnly=false,alphabetical=false,saveQueue=Promise.resolve(),pending=0;
const groups=[['all','▦','全部造物'],['new','✦','新發現'],['nature','☀️','自然'],['life','🌿','生命'],['craft','⚒️','人造'],['fantasy','🔮','想像'],['concept','◈','抽象概念']];
function category(e){if(e.concept)return 'concept';if(/精靈|宇宙|銀河|能量/.test(e.name))return 'fantasy';if(/植物|樹|森林|花|生命|魚|動物|鳥|茶/.test(e.name))return 'life';if(/金屬|工具|電|玻璃|沙漏|燈泡|船|木材|炭|房|村|城市|沙堡|磚|牆|烤/.test(e.name))return 'craft';return 'nature'}
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function storageStatus(message,error=false){$('#storageStatus').textContent=message;$('#storageStatus').classList.toggle('error',error);$('#retry').hidden=!error}
async function api(path,body){const res=await fetch(path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(30000)});if(!res.ok){let message;try{message=(await res.json()).error}catch{}throw Error(message||`服務未就緒（${res.status}）`)}return res.json()}
function snapshot(){return {elements,history,cache,settings}}
function localBackup(){try{localStorage.setItem(storageKey,JSON.stringify(snapshot()))}catch{}}
function save(){localBackup();const data=JSON.parse(JSON.stringify(snapshot()));pending++;storageStatus('◌ 正在寫入本機資料庫…');saveQueue=saveQueue.catch(()=>{}).then(()=>api('/api/state',data)).then(()=>{if(pending===1)storageStatus('✓ 已儲存至本機資料庫');return true}).catch(()=>{storageStatus('儲存未完成，請重試並保持此頁開啟',true);return false}).finally(()=>pending--);return saveQueue}
async function initialize(){ready=false;renderSlots();storageStatus('◌ 正在讀取本機資料庫…');try{let state=await api('/api/state');let old;try{old=JSON.parse(localStorage.getItem(storageKey)||'null')}catch{}
 if(old&&Array.isArray(old.elements)&&Array.isArray(old.history)){const incoming={elements:[],history:[],cache:{}};for(const e of old.elements)try{incoming.elements.push({...validateResult({...e,reason:e.reason||'已收藏'}),favorite:e.favorite})}catch{}for(const h of old.history)try{if(typeof h.a==='string'&&typeof h.b==='string')incoming.history.push({...h,result:validateResult(h.result)})}catch{}for(const [k,v]of Object.entries(old.cache||{}))try{incoming.cache[k]=validateResult(v)}catch{}if(state.elements.length===4&&state.history.length===0&&old.settings&&['classic','llm'].includes(old.settings.mode)&&typeof old.settings.endpoint==='string')incoming.settings=old.settings;state=await api('/api/state',incoming)}
 elements=state.elements;history=state.history;cache=state.cache;settings=state.settings;ready=true;localBackup();storageStatus('✓ 已連接本機資料庫 · 進度自動儲存');render()}catch{storageStatus('無法讀取資料庫，請啟動本機伺服器後重試',true);resultView('暫時無法載入進度','資料庫尚未連接，既有資料不會被清除。請使用 npm start 啟動遊戲。','⚠️','error');renderSlots()}}
function render(){const q=$('#search').value.trim().normalize('NFKC').toLowerCase();const terms=q.split(/\s+/).filter(Boolean);let visible=elements.filter(e=>q?terms.every(term=>e.name.normalize('NFKC').toLowerCase().includes(term)):(!favoritesOnly||e.favorite)&&(filter==='all'||(filter==='new'?!base.some(b=>b.name===e.name):category(e)===filter)));$('#clearSearch').hidden=!q;if(alphabetical)visible.sort((a,b)=>a.name.localeCompare(b.name,'zh-Hant'));else visible.reverse();$('#elements').replaceChildren();for(const e of visible){const cls=['fantasy','concept'].includes(category(e))?'purple':category(e)==='craft'?'blue':base.some(b=>b.name===e.name)?'gold':'';const wrap=node('div',undefined,'element-wrap '+cls),b=node('button',undefined,'element'),star=node('button',e.favorite?'★':'☆','star'+(e.favorite?' saved':''));b.append(node('span',e.emoji),node('strong',e.name));b.draggable=true;b.title=e.reason||e.name;b.onclick=()=>select(e);b.ondragstart=ev=>ev.dataTransfer.setData('text/plain',e.name);star.setAttribute('aria-label',(e.favorite?'取消收藏':'收藏')+e.name);star.setAttribute('aria-pressed',String(!!e.favorite));star.onclick=async()=>{const value=!e.favorite;star.disabled=true;try{await api('/api/favorite',{name:e.name,favorite:value});e.favorite=value;localBackup();storageStatus('✓ 收藏已儲存至本機資料庫');render()}catch{storageStatus('收藏未儲存，請稍後再試',true);star.disabled=false}};wrap.append(b,star);$('#elements').append(wrap)}if(!visible.length)$('#elements').append(node('p',q?'全櫃沒有符合的造物名稱，請換個關鍵字試試。':favoritesOnly?'點擊造物旁的 ☆，把它加入收藏。':'這裡還沒有造物。試著合成新的材料吧！','empty'));
 $('#categories').replaceChildren();for(const [id,icon,label]of groups){const count=elements.filter(e=>id==='all'||(id==='new'?!base.some(b=>b.name===e.name):category(e)===id)).length;const b=node('button',undefined,!q&&id===filter?'active':'');b.append(node('span',icon),node('small',count));b.title=label;b.setAttribute('aria-label',`${label}，${count} 個`);b.setAttribute('aria-pressed',String(!q&&id===filter));b.onclick=()=>{$('#search').value='';filter=id;render()};$('#categories').append(b)}$('#viewLabel').textContent=q?'全櫃搜尋 · 名稱':(favoritesOnly?'收藏 / ':'')+groups.find(g=>g[0]===filter)[2];$('#visibleCount').textContent=q?`找到 ${visible.length} / ${elements.length} 個`:visible.length+' 個';$('#favoriteCount').textContent=elements.filter(e=>e.favorite).length;$('#favorites').setAttribute('aria-pressed',String(!q&&favoritesOnly));$('#favorites').disabled=!!q;$('#favorites').title=q?'清空搜尋後恢復收藏篩選':'只顯示收藏';$('#sort span').textContent=alphabetical?'名稱':'最新';$('#sort').title=alphabetical?'切換為最新發現優先':'切換為名稱排序';$('#count').textContent=elements.length;$('#discoveryCount').textContent=elements.length-4;$('#recordCount').textContent=history.length;$('#modeLabel').textContent=settings.mode==='classic'?'經典配方':'LLM 自由聯想';$('#history').replaceChildren();if(!history.length)$('#history').append(node('p','還沒有合成紀錄，試試水 ＋ 火。','empty'));for(const h of history){const row=node('div',undefined,'history-row');row.append(node('span',h.kind==='extract'?`萃取 · ${h.a}`:`${h.a} + ${h.b}`),node('strong',`${h.result.emoji} ${h.result.name}`),node('small',h.new?'新發現':'已發現'));$('#history').append(row)}renderSlots()}
function select(e,index){if(busy||!ready)return;const i=index??(slots[0]?1:0);slots[i]=e;renderSlots()}
function renderSlots(){slots.forEach((e,i)=>{const s=$('#slot'+i);s.replaceChildren();if(e)s.append(node('span',e.emoji,'slot-icon'));s.append(node('strong',e?e.name:'點選材料'));s.classList.toggle('filled',!!e);s.disabled=busy||!ready;s.title=e?'點擊移除材料':'點選或拖曳一個造物'});const count=slots.filter(Boolean).length;
 $('#combine').disabled=!ready||busy||count!==2;$('#extract').disabled=!ready||busy||count!==1;
 $('#combine').textContent=busy&&count===2?'合成中…':'＋ 合成';$('#extract').textContent=busy&&count===1?'萃取中…':'◈ 萃取';
 const hint=!ready?'正在載入進度…':busy?'正在處理，請稍候…':count===0?'放入 1 個材料萃取，或 2 個材料合成':count===1?'已放入 1 個材料 · 可以萃取':'已放入 2 個材料 · 可以合成';
 $('#actionHint').textContent=hint;$('#operationHint').textContent='1 個材料萃取 · 2 個材料合成 · 材料不會消耗';
 $('#clear').disabled=busy;$('#settings').disabled=busy||!ready;$('.workbench').classList.toggle('busy',busy)}
function resultView(title,description,emoji,kind,isNew=false){const r=$('#result');r.className='result '+kind;const heading=node('h2',title);heading.id='resultTitle';if(isNew)heading.append(node('span','新發現','badge'));const body=node('div');const detail=node('p',description);detail.id='resultDescription';body.append(heading,detail);r.replaceChildren(node('span',emoji,'result-mark'),body);if(!$('#resultDialog').open)$('#resultDialog').showModal()}
$('#resultDialog').addEventListener('click',()=>$('#resultDialog').close());
async function combine(){if(!ready||busy||slots.some(x=>!x))return;busy=true;renderSlots();const [a,b]=slots;try{let r;const k=settings.mode==='classic'?'classic:'+key(a.name,b.name):JSON.stringify([settings.endpoint,key(a.name,b.name)]);if(settings.mode==='classic'){r=recipes.get(key(a.name,b.name));await new Promise(resolve=>setTimeout(resolve,200))}else{r=cache[k];if(!r)r=validateResult(await api(settings.endpoint||'/api/combine',{a:a.name,b:b.name}))}
 if(!r){resultView('這組材料還沒有配方','換一組材料試試，或接入 LLM 探索更多可能。','🫧','');return {found:false}}r=validateResult(r);cache[k]=r;const isNew=!elements.some(e=>e.name===r.name);if(isNew)elements.push({...r,favorite:false});history.unshift({id:crypto.randomUUID(),createdAt:new Date().toISOString(),a:a.name,b:b.name,result:r,new:isNew});history=history.slice(0,200);render();resultView(r.name,r.reason,r.emoji,'success',isNew);const persisted=await save();return {found:true,...r,new:isNew,persisted}}catch(e){resultView('這次合成沒有完成',e.name==='TimeoutError'?'等待模型超時，請稍後重試。':e instanceof TypeError?'無法連接合成服務，請檢查網址及服務是否已啟動。':e.message,'☁️','error');return {error:true}}finally{slots=[null,null];busy=false;renderSlots()}}
async function extract(){
 if(!ready||busy||slots.filter(Boolean).length!==1)return;busy=true;renderSlots();const source=slots.find(Boolean);
 try{const k='extract:'+JSON.stringify([settings.mode,settings.extractEndpoint||'',source.name]);let r=cache[k];if(!r){r=settings.mode==='classic'?extractions.get(source.name):await api(settings.extractEndpoint||'/api/extract',{source:source.name});}
 if(!r){resultView('這個造物還沒有萃取配方','換一個造物試試，或使用 LLM 萃取它的抽象概念。','◈','');return {found:false}}
 r=validateResult(r);if(r.name===source.name)throw Error('萃取結果與來源相同，請換個造物重試。');cache[k]=r;const existing=elements.find(e=>e.name===r.name),isNew=!existing;if(isNew)elements.push({...r,favorite:false,concept:true});else existing.concept=true;
 history.unshift({id:crypto.randomUUID(),createdAt:new Date().toISOString(),kind:'extract',a:source.name,b:'',result:r,new:isNew});history=history.slice(0,200);render();resultView(r.name,`萃取自「${source.name}」：${r.reason}`,r.emoji,'success',isNew);const persisted=await save();return {found:true,...r,new:isNew,persisted};
 }catch(e){resultView('這次萃取沒有完成',e.name==='TimeoutError'?'等待模型超時，請稍後重試。':e instanceof TypeError?'無法連接萃取服務，請檢查服務網址。':e.message,'◈','error');return {error:true}}finally{slots=[null,null];busy=false;renderSlots()}
}
slots.forEach((_,i)=>{const s=$('#slot'+i);s.onclick=()=>{if(!busy){slots[i]=null;renderSlots()}};s.ondragover=e=>{e.preventDefault();if(!busy)s.classList.add('drag')};s.ondragleave=()=>s.classList.remove('drag');s.ondrop=e=>{e.preventDefault();s.classList.remove('drag');const item=elements.find(x=>x.name===e.dataTransfer.getData('text/plain'));if(item)select(item,i)}});$('#combine').onclick=combine;$('#extract').onclick=extract;$('#clear').onclick=()=>{slots=[null,null];renderSlots()};$('#search').oninput=render;$('#clearSearch').onclick=()=>{$('#search').value='';render();$('#search').focus()};$('#search').onkeydown=e=>{if(e.key==='Escape'){$('#search').value='';render()}};$('#sort').onclick=()=>{alphabetical=!alphabetical;render()};$('#favorites').onclick=()=>{favoritesOnly=!favoritesOnly;render()};$('#historyButton').onclick=()=>$('#historyDialog').showModal();$('#closeHistory').onclick=()=>$('#historyDialog').close();$('#retry').onclick=()=>ready?save():initialize();$('#settings').onclick=()=>{$('#mode').value=settings.mode;$('#endpoint').value=settings.endpoint;$('#extractEndpoint').value=settings.extractEndpoint||'';$('#settingsError').textContent='';$('#dialog').showModal()};$('#close').onclick=()=>$('#dialog').close();$('#settingsForm').onsubmit=async e=>{e.preventDefault();const endpoint=$('#endpoint').value.trim();const extractEndpoint=$('#extractEndpoint').value.trim();try{for(const address of [endpoint,extractEndpoint])if(address){const u=new URL(address,location.origin);if(u.username||u.password||u.hash||!(u.protocol==='https:'||(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname))))throw Error()}}catch{$('#settingsError').textContent='請使用 HTTPS 服務網址，或 localhost 本機網址。';return}settings={mode:$('#mode').value,endpoint,extractEndpoint};render();if(await save())$('#dialog').close();else $('#settingsError').textContent='設定未儲存，請重試。'};
let dictionaryEntries=[],dictionarySelection=null;
function showDictionaryEntry(entry){dictionarySelection=entry.name;for(const b of $('#dictionaryList').children)b.setAttribute('aria-pressed',String(b.dataset.name===entry.name));const detail=$('#dictionaryDetail');detail.replaceChildren(node('div',entry.emoji,'dictionary-emoji'),node('h3',entry.name),node('p',entry.reason,'dictionary-reason'),node('h4','已發現的來源'));if(!entry.combinations.length&&!entry.extractions?.length)detail.append(node('p','這個造物的舊存檔沒有保留來源紀錄。再次發現後會自動補上。','muted'));for(const c of entry.combinations){const block=node('div',undefined,'dictionary-recipe');const a=elements.find(e=>e.name===c.a),b=elements.find(e=>e.name===c.b);block.append(node('strong',`${a?.emoji||'◈'} ${c.a} ＋ ${b?.emoji||'◈'} ${c.b}`),node('p',c.reason));detail.append(block)}for(const c of entry.extractions||[]){const block=node('div',undefined,'dictionary-recipe');block.append(node('strong',`◈ 萃取自：${c.source}`),node('p',c.reason));detail.append(block)}}
function renderDictionary(){const q=$('#dictionarySearch').value.trim().toLowerCase(),visible=dictionaryEntries.filter(e=>e.name.toLowerCase().includes(q));$('#dictionaryList').replaceChildren();for(const e of visible){const b=node('button',`${e.emoji} ${e.name}`,'dictionary-entry');b.dataset.name=e.name;b.setAttribute('aria-pressed',String(e.name===dictionarySelection));b.onclick=()=>showDictionaryEntry(e);$('#dictionaryList').append(b)}if(!visible.length){$('#dictionaryList').append(node('p',q?'沒有符合的造物。':'還沒有合成紀錄，先試試水 ＋ 火。','muted'));$('#dictionaryDetail').replaceChildren();return}showDictionaryEntry(visible.find(e=>e.name===dictionarySelection)||visible[0])}
async function loadDictionary(){const detail=$('#dictionaryDetail');$('#dictionaryList').replaceChildren();detail.replaceChildren(node('p','正在讀取字典…','muted'));try{await saveQueue;const data=await api('/api/dictionary');dictionaryEntries=data.entries;renderDictionary()}catch{detail.replaceChildren(node('p','無法讀取字典，請確認本機服務正常。','muted'));const retry=node('button','重試','primary');retry.onclick=loadDictionary;detail.append(retry)}}
$('#dictionaryButton').onclick=()=>{$('#dictionarySearch').value='';$('#dictionaryDialog').showModal();loadDictionary()};$('#closeDictionary').onclick=()=>$('#dictionaryDialog').close();$('#dictionarySearch').oninput=renderDictionary;
window.addEventListener('beforeunload',e=>{if(pending){e.preventDefault();e.returnValue=''}});render();await initialize();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'list_elements',description:'列出目前已發現的元素。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({elements:elements.map(({name,emoji,favorite})=>({name,emoji,favorite}))})},{name:'combine_elements',description:'合成兩個已發現的元素，更新收藏、紀錄與本機資料庫。',inputSchema:{type:'object',properties:{a:{type:'string'},b:{type:'string'}},required:['a','b'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(busy||!ready)throw Error('遊戲尚未就緒');const a=elements.find(e=>e.name===input?.a),b=elements.find(e=>e.name===input?.b);if(!a||!b)throw Error('只能合成已發現元素');slots=[a,b];renderSlots();return await combine()}},{name:'extract_concept',description:'從單一已發現造物萃取抽象概念，更新資料庫、字典和工作台。',inputSchema:{type:'object',properties:{source:{type:'string'}},required:['source'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(busy||!ready)throw Error('遊戲尚未就緒');const source=elements.find(e=>e.name===input?.source);if(!source)throw Error('只能萃取已發現造物');slots=[source,null];renderSlots();return await extract()}}])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
